const input = $('When Executed by Another Workflow').first().json;

const order = $('Collect Order').first().json.order;
const o = order[0] || null;

const opts = $input.all()
  .map(item => item.json)
  .filter(row => row.sku != null);

const wantSize = String(input.desired_size || '').trim().toLowerCase();
const wantColor = String(input.desired_color || '').trim().toLowerCase();

const currency = o ? String(o.currency) : '';

function money(value) {
  return (currency === 'INR' ? 'Rs ' : 'AED ') +
    Math.round(Number(value));
}

function output(ok, reason, list = [], left = 0) {
  return {
    eligible: String(ok),
    reason,
    item: o ? String(o.item ?? '') : '',
    size: o ? String(o.size ?? '') : '',
    sku: o ? String(o.sku ?? '') : '',
    paid: o ? String(o.amount ?? '') : '',
    currency,
    days_left: String(left),
    option_count: String(list.length),
    options: list.join('\n')
  };
}

let result;

// 1. Order not found
if (!o) {
  result = output(false, 'Order not found for this customer');
}

// 2. Already refunded
else if (
  String(o.refunded).toLowerCase() === 'yes' ||
  o.refunded === true ||
  Number(o.refund_count) > 0
) {
  result = output(false, 'This order was already refunded');
}

// 3. Return already exists
else if (Number(o.return_count) > 0) {
  result = output(false, 'A return is already in progress for this order');
}

// 4. Exchange already exists
else if (Number(o.exchange_count) > 0) {
  result = output(false, 'An exchange is already in progress for this order');
}

// 5. Order not delivered
else if (String(o.order_status).toLowerCase() !== 'delivered') {
  result = output(false, 'The order has not been delivered yet');
}

// 6. Missing delivery or policy information
else if (o.days_since_delivery == null ||
         o.return_window_days == null) {
  result = output(false, 'Cannot verify delivery date or exchange window');
}

else {
  const days = Number(o.days_since_delivery);
  const windowDays = Number(o.return_window_days);
  const left = windowDays - days;

  // 7. Exchange window expired
  if (left < 0) {
    result = output(
      false,
      `Delivered ${days} days ago; exchange window is ${windowDays} days`,
      [],
      left
    );
  }
  else {
    const paid = Number(o.amount);

    // 8. Exclude the original SKU and size combination
    let list = opts.filter(x =>
      !(x.sku === o.sku && String(x.size) === String(o.size))
    );

    let note = '';

    // 9. Filter by preferred size or color
    if (wantSize || wantColor) {
      const matches = list.filter(x =>
        (!wantSize || String(x.size).toLowerCase().includes(wantSize)) &&
        (!wantColor || String(x.color).toLowerCase().includes(wantColor))
      );

      if (matches.length > 0) {
        list = matches;
      } else if (list.length > 0) {
        note = 'No exact preference match; showing other choices. ';
      }
    }

    // 10. Format the top 5 replacement options
    const lines = list.slice(0, 5).map((x, i) => {
      const credit = paid - Number(x.price);

      const difference = credit > 0.5
        ? `${money(credit)} would be credited back`
        : 'same price';

      return `${i + 1}) ${x.name} (sku ${x.sku}), ` +
        `size ${x.size}, ${money(x.price)}, ` +
        `${x.stock_quantity} in stock, ${difference}`;
    });

    if (lines.length === 0) {
      result = output(
        false,
        'Nothing else is in stock at the same price or lower',
        [],
        left
      );
    } else {
      result = output(true, note + 'Eligible', lines, left);
    }
  }
}

return [{ json: result }];

